func (q *Queries) GetLatestContentRevisionByRepository(ctx context.Context, repositoryID pgtype.UUID) (ContentRevision, error) {
	row := q.db.QueryRow(ctx, getLatestContentRevisionByRepository, repositoryID)
	var i ContentRevision
	err := row.Scan(
		&i.ID,
		&i.RepositoryID,
		&i.CommitSha,
		&i.Ref,
		&i.Valid,
		&i.ValidationErrors,
		&i.ValidatedAt,
		&i.CreatedAt,
		&i.CommitMessage,
		&i.CommitAuthor,
		&i.CommittedAt,
	)
	return i, err
}

