const listPersonByRevision = `-- name: ListPersonByRevision :many
SELECT person.id, person.people_source_id, person.username, person.attributes, people_source.name AS people_source_name
FROM person
JOIN people_source ON people_source.id = person.people_source_id
WHERE people_source.content_revision_id = $1
ORDER BY people_source.name, person.username
`

type ListPersonByRevisionRow struct {
	ID               pgtype.UUID     `json:"id"`
	PeopleSourceID   pgtype.UUID     `json:"people_source_id"`
	Username         string          `json:"username"`
	Attributes       json.RawMessage `json:"attributes"`
	PeopleSourceName string          `json:"people_source_name"`
}

// Every person from every people CSV in one content revision -- "the user
// database from this repo's CSVs," searchable (the People
// screen). people_source_name lets the UI show which CSV a row came from
// without a second round trip.
func (q *Queries) ListPersonByRevision(ctx context.Context, contentRevisionID pgtype.UUID) ([]ListPersonByRevisionRow, error) {
	rows, err := q.db.Query(ctx, listPersonByRevision, contentRevisionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPersonByRevisionRow
	for rows.Next() {
		var i ListPersonByRevisionRow
		if err := rows.Scan(
			&i.ID,
			&i.PeopleSourceID,
			&i.Username,
			&i.Attributes,
			&i.PeopleSourceName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

